-- Guest Hub H9 fix 3 (17 Nov 2026, Ahmed — DECISIONS.md 2026-11-17 «Guest Hub: prices by date, dates in code with Hijri,
-- corrections, frustration vs complaints, staff voice and tab, reply rules, stronger models, standby visibility, reminders, test
-- numbers»). Generated by scripts/hub-fix3-migration.mjs from scripts/hub-fix3-migration.src.sql and the latest definitions of
-- the functions it edits — never edited once applied (CLAUDE.md §12: a fix is a new migration).
--   The models: understanding, tagging, translation and images on claude-sonnet-5-5; the staff path on claude-opus-5-5.
--   Reply rules: a card is a fact or a rule («قاعدة رد — أحمد — {date}», Ahmed only); the knowledge read returns rules apart.
--   «وضع الاستعداد»: every turn records why it waited or not; the exchange ends after 30 minutes without a message; the
--   standby card's live line. «تذكير رفع القائمة»: the upload reminders on their own switch (default ON). «أرقام التجربة»:
--   up to 5 guest-path numbers that book test reservations. Staff voice notes (the unit's daily minutes) and «المحادثات» →
--   «الفريق». «يحتاج قرارك» in «قاعدة المعرفة». The bank: q015 / q083 notes, the fix-3 conversations as lab items.
-- No unit mode, licence or switch changes (the new reminder switch is ON by Ahmed's decision; the sending switches are
-- untouched). No phone number in this file. Every UPDATE / DELETE carries a WHERE.


-- ───────────────────────────────────────────── 1. the models (Ahmed, 17 Nov 2026) ─────────────────────────────────────────────
-- understanding, tagging, translation and images (and the staff alert's line, which reads hub_models.understand) on
-- claude-sonnet-5-5; the staff path (the colleague chat, the staff intent, teaching and reply rules, the reminders) on
-- claude-opus-5-5 (the new key `staff`, also `draft_card`); compose / suggest stay claude-sonnet-5-5. The Opus price read
-- from Anthropic's model table on 17 Nov 2026 (USD 4 / 20 per million tokens, cache reads 0.20).
update public.settings
   set value = value || jsonb_build_object('understand', 'claude-sonnet-5-5', 'tag', 'claude-sonnet-5-5', 'translate', 'claude-sonnet-5-5',
                                           'vision', 'claude-sonnet-5-5', 'staff', 'claude-opus-5-5', 'draft_card', 'claude-opus-5-5')
 where key = 'hub_models' and jsonb_typeof(value) = 'object';
update public.settings
   set value = value || jsonb_build_object('claude-opus-5-5', jsonb_build_object('input', 4, 'output', 20, 'cache_read', 0.2,
                                           'source', 'https://platform.claude.com/docs/en/about-claude/models', 'read_at', '2026-11-17'))
 where key = 'hub_model_prices' and jsonb_typeof(value) = 'object' and not (value ? 'claude-opus-5-5');

-- ───────────────────────────────────────────── 2. reply rules (Ahmed, 17 Nov 2026) ─────────────────────────────────────────────
-- a card is a FACT (what guests are told) or a RULE (how to answer a topic — «قاعدة رد», taught by Ahmed only). The knowledge
-- read never returns a rule among the facts: rules travel apart (`rules`) and compose follows them (prompts.md §2).
alter table public.hub_knowledge_cards add column card_kind text not null default 'fact' check (card_kind in ('fact', 'rule'));
comment on column public.hub_knowledge_cards.card_kind is 'H9 fix 3 (Ahmed, 17 Nov 2026): fact = what guests are told; rule = how to answer a topic («قاعدة رد — أحمد — {date}»), never a fact, never in the guard''s facts.';
-- the library view again, so it carries card_kind (a view keeps the columns it was created with)
drop view public.hub_cards_library;
create view public.hub_cards_library with (security_invoker = true) as
  select c.*, internal.hub_card_pending(c) as pending, internal.hub_card_check(c) as "check",
         case when c.status = 'archived' then 'archived'
              when c.live is null then 'draft'
              when (c.live ->> 'expires_on') is not null and (c.live ->> 'expires_on')::date < internal.riyadh_today() then 'expired'
              else 'published' end as state,
         (select s.full_name from public.staff s where s.user_id = c.verified_by) as verified_by_name
    from public.hub_knowledge_cards c;
comment on view public.hub_cards_library is 'hub_knowledge_cards + pending + check + state (draft | published | expired | archived) + the verifier''s name. RLS of the cards applies (security invoker). H6: + price_note, draft_origin. H7b: + the learn columns. H9 fix 3: + card_kind.';
revoke all on public.hub_cards_library from public, anon, authenticated;
grant select on public.hub_cards_library to authenticated, service_role;

-- ───────────────────────────────────────────── 3. «وضع الاستعداد» visible (Ahmed, 17 Nov 2026) ─────────────────────────────────────────────
-- every guest turn records why it waited or not: waiting (ينتظر رد الفريق) · off (the switch) · no_shift (nobody on shift
-- now) · engaged (the exchange with the assistant is running) · tap (one of our buttons) · tag (with staff — no reply)
alter table public.hub_turns add column standby_reason text check (standby_reason is null or standby_reason in ('waiting', 'off', 'no_shift', 'engaged', 'tap', 'tag'));
comment on column public.hub_turns.standby_reason is 'H9 fix 3: why the turn waited for a staff reply or not (shown in «المحادثات» and «المحاكي»).';

-- the exchange with the assistant ends after 30 minutes without a message: a guest who writes again later waits again
create function internal.hub_exchange_open(p_conversation uuid, p_message uuid, p_at timestamptz default now()) returns boolean
language sql stable security definer set search_path = '' as $$
  select exists (select 1 from public.hub_messages m where m.conversation_id = p_conversation and m.id is distinct from p_message
                    and m.direction in ('in', 'out') and m.created_at > p_at - interval '30 minutes' and m.created_at <= p_at)
$$;

create function internal.hub_standby_reason(p_conversation uuid, p_message uuid, p_kind text, p_at timestamptz default now()) returns text
language sql stable security definer set search_path = '' as $$
  select case
    when p_kind <> 'reply' then 'tag'
    when exists (select 1 from public.hub_messages m where m.id = p_message and (m.kind in ('interactive', 'button_reply') or m.payload ? 'button_id')) then 'tap'
    when not coalesce(t.standby_on, false) or coalesce(t.standby_minutes, 0) not between 1 and 30 then 'off'
    when internal.hub_assistant_engaged(p_conversation) and internal.hub_exchange_open(p_conversation, p_message, p_at) then 'engaged'
    when not exists (select 1 from public.hub_staff_slots s where s.branch_slug = u.branch_slug and s.active and internal.hub_slot_covers(s, p_at)) then 'no_shift'
    else 'waiting' end
    from public.hub_conversations c join public.hub_units u on u.id = c.unit_id left join public.hub_team_branches t on t.branch_slug = u.branch_slug
   where c.id = p_conversation
$$;

-- the rule of H9 fix 2 with the 30-minute exchange: the minutes only while the reason is «waiting»
create or replace function internal.hub_standby_minutes(p_conversation uuid, p_message uuid, p_kind text, p_at timestamptz default now()) returns integer
language sql stable security definer set search_path = '' as $$
  select case when internal.hub_standby_reason(p_conversation, p_message, p_kind, p_at) = 'waiting' then t.standby_minutes end
    from public.hub_conversations c join public.hub_units u on u.id = c.unit_id join public.hub_team_branches t on t.branch_slug = u.branch_slug
   where c.id = p_conversation and t.standby_on and t.standby_minutes between 1 and 30
$$;

-- «الآن: ينتظر / لا ينتظر — السبب» on the standby card, and the simulator's line (the shift in Asia/Riyadh, midnight-crossing
-- and 23:45 ends included — internal.hub_slot_covers)
create function public.hub_standby_now(p_branch text) returns jsonb
language plpgsql stable security definer set search_path = '' as $$
declare t public.hub_team_branches;
begin
  if not (internal.can('hub_team', 'view') or internal.can('assistant', 'view') or internal.hub_is_service()) then raise exception 'forbidden' using errcode = '42501'; end if;
  select * into t from public.hub_team_branches where branch_slug = p_branch;
  if t.branch_slug is null then raise exception 'not_found' using errcode = '22023'; end if;
  return jsonb_build_object('branch', p_branch, 'on', t.standby_on, 'minutes', t.standby_minutes, 'at', now(),
    'riyadh', to_char(now() at time zone 'Asia/Riyadh', 'HH24:MI'),
    'on_shift', (select coalesce(jsonb_agg(s.name order by s.position), '[]'::jsonb) from public.hub_staff_slots s
                  where s.branch_slug = p_branch and s.active and internal.hub_slot_covers(s, now())),
    'reason', case when not t.standby_on then 'off'
                   when not exists (select 1 from public.hub_staff_slots s where s.branch_slug = p_branch and s.active and internal.hub_slot_covers(s, now())) then 'no_shift'
                   else 'waiting' end);
end;
$$;
grant execute on function public.hub_standby_now(text) to authenticated, service_role;
revoke execute on function public.hub_standby_now(text) from public, anon;

-- the last reply turn of a conversation: its reason, its wait and how it ended (the thread header)
create function internal.hub_standby_last(p_conversation uuid) returns jsonb
language sql stable security definer set search_path = '' as $$
  select jsonb_build_object('reason', t.standby_reason, 'until', t.standby_until, 'outcome', t.standby_outcome, 'at', t.created_at)
    from public.hub_turns t where t.conversation_id = p_conversation and t.kind = 'reply' and t.standby_reason is not null
   order by t.created_at desc limit 1
$$;
revoke execute on function internal.hub_exchange_open(uuid, uuid, timestamptz), internal.hub_standby_reason(uuid, uuid, text, timestamptz), internal.hub_standby_last(uuid)
  from public, anon, authenticated;

-- ───────────────────────────────────────────── 4. «تذكير رفع القائمة» (Ahmed, 17 Nov 2026) ─────────────────────────────────────────────
-- the upload reminders and the 08:30 alert run on their own per-branch switch (default ON), whatever the two sending
-- switches say. On 17 Nov 2026 none ran: internal.hub_departures_in_use asked for a sending switch on or an upload in the last
-- 7 days, and both switches were off until 17:42 Riyadh with no upload ever.
alter table public.hub_departure_config add column remind_on boolean not null default true;
comment on column public.hub_departure_config.remind_on is 'H9 fix 3 (Ahmed, 17 Nov 2026): «تذكير رفع القائمة» — the 07:00 / 08:00 reminders and the 08:30 alert, independent of check_on / review_on. Default ON.';
drop trigger hub_departure_config_audit on public.hub_departure_config;
create trigger hub_departure_config_audit after insert or update or delete on public.hub_departure_config
  for each row execute function internal.audit('branch_slug', 'check_on', 'review_on', 'remind_on');
create or replace function internal.hub_departures_in_use(p_branch text, p_now timestamptz, p_test boolean) returns boolean
language sql stable security definer set search_path = '' as $$
  select coalesce((select f.remind_on from public.hub_departure_config f where f.branch_slug = p_branch), false)
$$;
create function public.hub_departure_remind_set(p_branch text, p_on boolean) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare f public.hub_departure_config;
begin
  if not internal.is_system_admin() then raise exception 'forbidden' using errcode = '42501'; end if;
  if p_on is null then raise exception 'invalid' using errcode = '22023'; end if;
  select * into f from public.hub_departure_config where branch_slug = p_branch for update;
  if f.branch_slug is null then raise exception 'not_found' using errcode = '22023'; end if;
  perform set_config('app.actor', coalesce(auth.uid()::text, 'departures'), true);
  update public.hub_departure_config set remind_on = p_on where branch_slug = p_branch;
  return jsonb_build_object('ok', true, 'previous', jsonb_build_object('remind_on', f.remind_on));
end;
$$;
grant execute on function public.hub_departure_remind_set(text, boolean) to authenticated;
revoke execute on function public.hub_departure_remind_set(text, boolean) from public, anon;

-- ───────────────────────────────────────────── 5. «أرقام التجربة» (Ahmed, 17 Nov 2026) ─────────────────────────────────────────────
-- up to 5 numbers (the system admin's) that go through the GUEST path but book only TEST reservations — as «يُعامَل كضيف
-- للتجربة» does for a staff number. Never a staff number, never written in a file.
create table public.hub_test_numbers (
  id uuid primary key default gen_random_uuid(),
  phone text not null unique check (phone ~ '^\+[1-9][0-9]{7,14}$'),
  label text not null default '' check (char_length(label) <= 40),
  created_by uuid,
  created_at timestamptz not null default now()
);
comment on table public.hub_test_numbers is 'H9 fix 3 (Ahmed, 17 Nov 2026): «أرقام التجربة» — up to 5 numbers on the guest path whose chat bookings are TEST reservations (internal.hub_test_guest). The system admin only.';
alter table public.hub_test_numbers enable row level security;
revoke all on table public.hub_test_numbers from public, anon, authenticated;
grant all on table public.hub_test_numbers to service_role;
create trigger hub_test_numbers_audit after insert or update or delete on public.hub_test_numbers for each row execute function internal.audit('id', 'label');

create or replace function internal.hub_test_guest(p_phone text) returns boolean
language sql stable security definer set search_path = '' as $$
  select coalesce((internal.hub_staff_lookup(p_phone) ->> 'test_as_guest')::boolean, false)
      or exists (select 1 from public.hub_test_numbers n where n.phone = p_phone)
$$;
create function public.hub_test_number_save(p_phone text, p_label text default '') returns jsonb
language plpgsql security definer set search_path = '' as $$
declare v public.hub_test_numbers;
begin
  if not internal.is_system_admin() then raise exception 'forbidden' using errcode = '42501'; end if;
  if p_phone is null or p_phone !~ '^\+[1-9][0-9]{7,14}$' then raise exception 'invalid_phone' using errcode = '22023'; end if;
  if internal.hub_staff_lookup(p_phone) is not null then raise exception 'staff_number' using errcode = '22023'; end if;
  if (select count(*) from public.hub_test_numbers) >= 5 and not exists (select 1 from public.hub_test_numbers n where n.phone = p_phone) then
    raise exception 'too_many' using errcode = '22023';
  end if;
  perform set_config('app.actor', auth.uid()::text, true);
  insert into public.hub_test_numbers (phone, label, created_by) values (p_phone, left(btrim(coalesce(p_label, '')), 40), auth.uid())
  on conflict (phone) do update set label = excluded.label
  returning * into v;
  return jsonb_build_object('ok', true, 'id', v.id);
end;
$$;
create function public.hub_test_number_delete(p_id uuid) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare v public.hub_test_numbers;
begin
  if not internal.is_system_admin() then raise exception 'forbidden' using errcode = '42501'; end if;
  perform set_config('app.actor', auth.uid()::text, true);
  delete from public.hub_test_numbers where id = p_id returning * into v;
  if v.id is null then raise exception 'not_found' using errcode = '22023'; end if;
  return jsonb_build_object('ok', true, 'previous', jsonb_build_object('phone', v.phone, 'label', v.label));
end;
$$;
grant execute on function public.hub_test_number_save(text, text), public.hub_test_number_delete(uuid) to authenticated;
revoke execute on function public.hub_test_number_save(text, text), public.hub_test_number_delete(uuid) from public, anon;

-- ───────────────────────────────────────────── 6. staff voice notes and «الفريق» in «المحادثات» (Ahmed, 17 Nov 2026) ─────────────────────────────────────────────
alter table public.hub_staff_messages add column kind text not null default 'text' check (kind in ('text', 'audio', 'button'));
alter table public.hub_staff_messages add column audio_seconds numeric(8, 2);
comment on column public.hub_staff_messages.kind is 'H9 fix 3: a staff or management voice note is transcribed (gpt-transcribe, the unit''s daily minutes) and its transcript is the body.';

-- the minutes of the staff's voice notes count toward the unit's daily cap (source staff)
create or replace function internal.hub_voice_state(p_unit uuid, p_now timestamptz default now()) returns jsonb
language sql stable security definer set search_path = '' as $$
  select jsonb_build_object(
    'cap_seconds', internal.hub_setting_int('hub_voice_daily_minutes', 60) * 60,
    'used_seconds', coalesce((select sum(d.audio_seconds) from public.hub_usage_daily d
                               where d.unit_id = p_unit and d.layer = 'transcribe' and d.source in ('turn', 'staff') and not d.is_test
                                 and d.day = (p_now at time zone 'Asia/Riyadh')::date), 0),
    'day', (p_now at time zone 'Asia/Riyadh')::date)
$$;

-- a staff voice note (service role, wa-automation): the seconds left today for the number's unit, then the transcription
-- recorded (its minutes and cost); a capped or a failed note gets the colleague line «اكتبها لي»
create function public.hub_staff_voice_gate(p_channel text) returns jsonb
language plpgsql stable security definer set search_path = '' as $$
declare ch public.hub_channels; st jsonb;
begin
  if not internal.hub_is_service() then raise exception 'forbidden' using errcode = '42501'; end if;
  select * into ch from public.hub_channels where address = p_channel order by created_at limit 1;
  if ch.id is null then return jsonb_build_object('ok', false, 'reason', 'no_channel'); end if;
  st := internal.hub_voice_state(ch.unit_id);
  return jsonb_build_object('ok', true, 'unit_id', ch.unit_id, 'left_seconds', greatest(0, (st ->> 'cap_seconds')::numeric - (st ->> 'used_seconds')::numeric),
    'model', coalesce((select s.value ->> 'transcribe' from public.settings s where s.key = 'hub_models'), 'gpt-transcribe'));
end;
$$;
create function public.hub_staff_voice_add(p_channel text, p_seconds numeric, p_test boolean default false) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare ch public.hub_channels; v_cost numeric;
begin
  if not internal.hub_is_service() then raise exception 'forbidden' using errcode = '42501'; end if;
  select * into ch from public.hub_channels where address = p_channel order by created_at limit 1;
  if ch.id is null then return jsonb_build_object('ok', false); end if;
  v_cost := internal.hub_audio_add(ch.unit_id, 'staff', coalesce((select s.value ->> 'transcribe' from public.settings s where s.key = 'hub_models'), 'gpt-transcribe'),
                                   least(greatest(coalesce(p_seconds, 0), 0), 600), coalesce(p_test, false));
  return jsonb_build_object('ok', true, 'cost_usd', v_cost);
end;
$$;
grant execute on function public.hub_staff_voice_gate(text), public.hub_staff_voice_add(text, numeric, boolean) to service_role;
revoke execute on function public.hub_staff_voice_gate(text), public.hub_staff_voice_add(text, numeric, boolean) from public, anon, authenticated;

-- «المحادثات» → «الفريق»: the conversations of staff and management numbers with the line (30 days), with what each
-- teaching became. The system admin sees every branch; a user with «الفريق والتقارير» edit sees the branches in scope.
create function internal.hub_staff_thread_allowed(p_branch text) returns boolean
language sql stable security definer set search_path = '' as $$
  select internal.is_system_admin() or (internal.can('hub_team', 'edit') and internal.can_branch(p_branch))
$$;
create function public.hub_staff_threads() returns jsonb
language plpgsql stable security definer set search_path = '' as $$
begin
  if not (internal.is_system_admin() or internal.can('hub_team', 'edit')) then raise exception 'forbidden' using errcode = '42501'; end if;
  return jsonb_build_object('rows', (select coalesce(jsonb_agg(x order by x ->> 'last_at' desc), '[]'::jsonb) from (
    select jsonb_build_object('who', m.who_kind || ':' || m.who_id, 'kind', m.who_kind, 'branch', u.branch_slug, 'unit', u.key,
             'name', coalesce((select s.name from public.hub_staff_slots s where s.id = m.who_id), (select r.name from public.hub_report_recipients r where r.id = m.who_id), '—'),
             'role', coalesce((select s.role from public.hub_staff_slots s where s.id = m.who_id), 'management'),
             'last_at', max(m.created_at), 'count', count(*),
             'teachings', count(*) filter (where exists (select 1 from public.hub_teach_jobs j where j.staff_message_id = m.id)),
             'cards', (select count(distinct j.card_id) from public.hub_teach_jobs j join public.hub_staff_messages mm on mm.id = j.staff_message_id
                        where mm.who_id = m.who_id and mm.channel_id = m.channel_id and j.card_id is not null)) as x
      from public.hub_staff_messages m join public.hub_channels ch on ch.id = m.channel_id join public.hub_units u on u.id = ch.unit_id
     where m.created_at > now() - interval '30 days' and not m.is_test and internal.hub_staff_thread_allowed(u.branch_slug)
     group by m.who_kind, m.who_id, m.channel_id, u.branch_slug, u.key) q));
end;
$$;
create function public.hub_staff_thread(p_who text, p_unit text) returns jsonb
language plpgsql stable security definer set search_path = '' as $$
declare u public.hub_units; v_kind text := split_part(p_who, ':', 1); v_id uuid;
begin
  begin
    v_id := split_part(p_who, ':', 2)::uuid;
  exception when others then raise exception 'invalid' using errcode = '22023';
  end;
  select * into u from public.hub_units where key = p_unit;
  if u.id is null or not internal.hub_staff_thread_allowed(u.branch_slug) then raise exception 'forbidden' using errcode = '42501'; end if;
  return jsonb_build_object('who', p_who, 'unit', u.key, 'branch', u.branch_slug,
    'messages', (select coalesce(jsonb_agg(jsonb_build_object('id', m.id, 'direction', m.direction, 'kind', m.kind, 'body', m.body, 'status', m.status,
                    'audio_seconds', m.audio_seconds, 'at', m.created_at,
                    'teach', (select jsonb_build_object('status', j.status, 'reason', j.reason, 'card', (select jsonb_build_object('id', k.id, 'key', k.key, 'kind', k.card_kind,
                                'text_ar', k.text_ar, 'status', k.status, 'source', k.source) from public.hub_knowledge_cards k where k.id = j.card_id))
                                from public.hub_teach_jobs j where j.staff_message_id = m.id order by j.created_at desc limit 1)) order by m.created_at), '[]'::jsonb)
                   from public.hub_staff_messages m join public.hub_channels ch on ch.id = m.channel_id
                  where m.who_kind = v_kind and m.who_id = v_id and ch.unit_id = u.id and m.created_at > now() - interval '30 days' and not m.is_test));
end;
$$;
grant execute on function public.hub_staff_threads(), public.hub_staff_thread(text, text) to authenticated;
revoke execute on function public.hub_staff_threads(), public.hub_staff_thread(text, text), internal.hub_staff_thread_allowed(text) from public, anon;

-- ───────────────────────────────────────────── 7. «يحتاج قرارك» in one place (Ahmed, 17 Nov 2026) ─────────────────────────────────────────────
alter table public.hub_card_jobs add column decided text check (decided is null or decided in ('approved', 'dismissed'));
alter table public.hub_card_jobs add column decided_at timestamptz;
alter table public.hub_card_jobs add column decided_by uuid;
comment on column public.hub_card_jobs.decided is 'H9 fix 3: «يحتاج قرارك» answered from «قاعدة المعرفة» → «يحتاج قرارك» — approved (a card made from it) or dismissed.';
create function public.hub_decisions_list() returns jsonb
language plpgsql stable security definer set search_path = '' as $$
begin
  if not internal.can('knowledge', 'view') then raise exception 'forbidden' using errcode = '42501'; end if;
  return jsonb_build_object('rows', (select coalesce(jsonb_agg(jsonb_build_object(
      'id', j.id, 'kind', j.decision ->> 'kind', 'at', j.finished_at, 'unit', u.key, 'branch', u.branch_slug, 'topic_key', q.topic_key,
      'unanswered_id', q.id,
      'question', case when internal.can_unit(j.unit_id, 'view') then q.question_excerpt end,
      'reply', case when internal.can_unit(j.unit_id, 'view') then left(m.body, 600) end,
      'staff', coalesce(internal.staff_name(m.staff_id), 'الجوال'),
      'conflicts', (select coalesce(jsonb_agg(jsonb_build_object('key', k.key, 'title_ar', k.title_ar, 'text_ar', k.text_ar)), '[]'::jsonb)
                      from public.hub_knowledge_cards k where k.key in (select jsonb_array_elements_text(coalesce(j.decision -> 'conflicts', '[]'::jsonb)))))
      order by j.finished_at desc), '[]'::jsonb)
    from public.hub_card_jobs j join public.hub_units u on u.id = j.unit_id join public.hub_unanswered q on q.id = j.unanswered_id
    join public.hub_messages m on m.id = j.staff_message_id
   where j.decision is not null and j.decided is null and not j.is_test and internal.can_branch(u.branch_slug)));
end;
$$;
create function public.hub_decision_set(p_job uuid, p_decided text, p_card uuid default null) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare j public.hub_card_jobs; u public.hub_units;
begin
  if not internal.can('knowledge', 'edit') then raise exception 'forbidden' using errcode = '42501'; end if;
  if p_decided not in ('approved', 'dismissed') then raise exception 'invalid' using errcode = '22023'; end if;
  select * into j from public.hub_card_jobs where id = p_job and decision is not null for update;
  if j.id is null then raise exception 'not_found' using errcode = '22023'; end if;
  select * into u from public.hub_units where id = j.unit_id;
  if not internal.can_branch(u.branch_slug) then raise exception 'forbidden' using errcode = '42501'; end if;
  if p_decided = 'approved' and (p_card is null or not exists (select 1 from public.hub_knowledge_cards k where k.id = p_card)) then raise exception 'card_required' using errcode = '22023'; end if;
  perform set_config('app.actor', auth.uid()::text, true);
  update public.hub_card_jobs set decided = p_decided, decided_at = now(), decided_by = auth.uid(), card_id = coalesce(p_card, card_id) where id = j.id;
  return jsonb_build_object('ok', true, 'previous', jsonb_build_object('decided', j.decided));
end;
$$;
grant execute on function public.hub_decisions_list(), public.hub_decision_set(uuid, text, uuid) to authenticated;
revoke execute on function public.hub_decisions_list(), public.hub_decision_set(uuid, text, uuid) from public, anon;

-- ───────────────────────────────────────────── 8. the banks: corrections and the new conversations ─────────────────────────────────────────────
-- q015 (a room price without dates) and q083 (a Hijri date): the H5 notes allowed «يبدأ من» and the Gregorian-only reply;
-- since H9 fix 3 both ask (the dates and guests; the Hijri date read by code) — the expect stays «ask», the notes change.
update public.hub_test_items set note = 'H9 fix 3: asks for the dates and the guests; never «يبدأ من» or a lowest price'
 where key = 'q015' and note = 'asks for dates; may give «يبدأ من» from room_from_prices only';
update public.hub_test_items set note = 'H9 fix 3: a Hijri date is read by code (Umm al-Qura) — the stay continues (the departure or the guests asked)'
 where key = 'q083' and note = 'Hijri date → copy.md §2.2';


-- ───────────────────────────────────────────── 10. the functions it edits ─────────────────────────────────────────────

create or replace function public.hub_knowledge_for(p_unit text, p_topics text[], p_language text, p_branch text default null) returns jsonb
language plpgsql stable security definer set search_path = '' as $$
declare
  u public.hub_units;
  v_keys text[];
  v_focus text[];
  v_named text[];
  v_hidden text[] := array(select x.key from public.hub_units x where x.knowledge_hidden);
  v_rel text[];
  v_n integer := greatest(internal.hub_setting_int('hub_cards_per_turn', 5), 1);
  v_lang text := case when p_language = 'en' then 'en' else 'ar' end;
  v_today date := internal.riyadh_today();
  v_cards jsonb;
  v_faq jsonb;
  -- H9 fix 3: the owner's reply rules for these topics (how to answer — never facts)
  v_rules jsonb;
begin
  select * into u from public.hub_units where key = p_unit;
  if u.id is null then raise exception 'hub_unit' using errcode = '22023'; end if;
  if u.knowledge_hidden or cardinality(coalesce(p_topics, '{}')) = 0 then
    return jsonb_build_object('unit', u.key, 'language', v_lang, 'cards', '[]'::jsonb, 'faq', '[]'::jsonb);
  end if;
  -- the number's own branch: every unit of it (a branch unit with its venues; a dining unit with its branch)
  v_keys := array(select x.key from public.hub_units x where x.branch_slug = u.branch_slug);
  -- the units of the branch the guest named (empty when none, «both» or this number's own branch)
  v_named := case when p_branch is not null and p_branch <> 'both' and p_branch <> u.branch_slug
                  then array(select x.key from public.hub_units x where x.branch_slug = p_branch) else '{}' end;
  v_focus := case when cardinality(v_named) > 0 then v_named else v_keys end;
  v_rel := array(select t.parent_key from public.hub_topics t where t.key = any (p_topics) and t.parent_key is not null
                 union select t.key from public.hub_topics t where t.parent_key = any (p_topics));
  select coalesce(jsonb_agg(jsonb_build_object('id', z.id, 'key', z.key, 'title', z.live ->> ('title_' || v_lang), 'text', z.live ->> ('text_' || v_lang),
                                               'source', z.live ->> 'source', 'source_date', z.live ->> 'source_date', 'unit_keys', z.live -> 'unit_keys',
                                               'topic_keys', z.live -> 'topic_keys',
                                               'branch', (select x.branch_slug from public.hub_units x where x.key = (z.live -> 'unit_keys' ->> 0))) order by z.rank_unit, z.exact desc, z.related desc, z.sort, z.key), '[]'::jsonb)
    into v_cards from (
      select c.id, c.key, c.live, c.sort,
             case when c.unit_keys <@ v_focus and cardinality(c.unit_keys) > 0 then 0
                  when c.unit_keys && v_focus then 1
                  when cardinality(c.unit_keys) = 0 then 2
                  else 3 end as rank_unit,
             (select count(*) from unnest(c.topic_keys) k where k = any (p_topics)) as exact,
             (select count(*) from unnest(c.topic_keys) k where k = any (v_rel)) as related
        from (select k.id, k.key, k.live, k.sort, array(select jsonb_array_elements_text(k.live -> 'unit_keys')) as unit_keys,
                     array(select jsonb_array_elements_text(k.live -> 'topic_keys')) as topic_keys
                from public.hub_knowledge_cards k
               where k.status = 'published' and k.live is not null and not k.is_test and k.card_kind = 'fact'
                 and ((k.live ->> 'expires_on') is null or (k.live ->> 'expires_on')::date >= v_today)) c
       where not (c.unit_keys && v_hidden)
         and (c.topic_keys && p_topics or c.topic_keys && v_rel)
         -- the café menu and ordering cards: on their own branch's numbers, or when the guest named that branch
         and (not (c.key = any (internal.hub_branch_only_cards())) or c.unit_keys && v_keys or c.unit_keys && v_named)
       order by rank_unit, exact desc, related desc, c.sort, c.key
       limit v_n) z;
  select coalesce(jsonb_agg(jsonb_build_object('key', z.key, 'q', z.live ->> ('q_' || v_lang), 'a', internal.hub_fill_fees(z.live ->> ('a_' || v_lang), v_lang))
                            order by z.mine desc, z.hits desc, z.sort, z.key), '[]'::jsonb)
    into v_faq from (
      select y.* from (
        select f.key, f.live, (f.live ->> 'sort')::int as sort,
               coalesce(t.unit_keys && v_focus, false) as mine,
               (select count(*) from unnest(coalesce(t.topic_keys, '{}')) k where k = any (p_topics)) * 2
               + (select count(*) from unnest(coalesce(t.topic_keys, '{}')) k where k = any (v_rel)) as hits
          from public.faq_items f left join public.hub_faq_topics t on t.faq_key = f.key
         where f.live is not null and not coalesce((f.live ->> 'hidden')::boolean, false) and not f.is_test) y
       where y.hits > 0
       order by y.mine desc, y.hits desc, y.sort, y.key
       limit v_n) z;
  select coalesce(jsonb_agg(jsonb_build_object('id', k.id, 'key', k.key, 'title', k.live ->> ('title_' || v_lang), 'text', k.live ->> ('text_' || v_lang), 'card_kind', 'rule')
                            order by k.sort, k.key), '[]'::jsonb)
    into v_rules from (select k.* from public.hub_knowledge_cards k
                        where k.card_kind = 'rule' and k.status = 'published' and k.live is not null and not k.is_test
                          and ((k.live ->> 'expires_on') is null or (k.live ->> 'expires_on')::date >= v_today)
                          and array(select jsonb_array_elements_text(k.live -> 'topic_keys')) && (p_topics || v_rel)
                          and (cardinality(array(select jsonb_array_elements_text(k.live -> 'unit_keys'))) = 0
                               or array(select jsonb_array_elements_text(k.live -> 'unit_keys')) && v_focus)
                        order by k.sort, k.key limit 5) k;
  return jsonb_build_object('unit', u.key, 'language', v_lang, 'branch', coalesce(p_branch, u.branch_slug), 'cards', v_cards, 'faq', v_faq, 'rules', v_rules);
end;
$$;

create or replace function public.hub_knowledge_for_eval(p_unit text, p_topics text[], p_language text, p_branch text default null, p_cards uuid[] default null) returns jsonb
language plpgsql stable security definer set search_path = '' as $$
declare
  u public.hub_units;
  v_keys text[];
  v_focus text[];
  v_named text[];
  v_hidden text[] := array(select x.key from public.hub_units x where x.knowledge_hidden);
  v_rel text[];
  v_n integer := greatest(internal.hub_setting_int('hub_cards_per_turn', 5), 1);
  v_lang text := case when p_language = 'en' then 'en' else 'ar' end;
  v_today date := internal.riyadh_today();
  v_cards jsonb;
  v_faq jsonb;
begin
  select * into u from public.hub_units where key = p_unit;
  if u.id is null then raise exception 'hub_unit' using errcode = '22023'; end if;
  if u.knowledge_hidden or cardinality(coalesce(p_topics, '{}')) = 0 then
    return jsonb_build_object('unit', u.key, 'language', v_lang, 'cards', '[]'::jsonb, 'faq', '[]'::jsonb);
  end if;
  -- the number's own branch: every unit of it (a branch unit with its venues; a dining unit with its branch)
  v_keys := array(select x.key from public.hub_units x where x.branch_slug = u.branch_slug);
  -- the units of the branch the guest named (empty when none, «both» or this number's own branch)
  v_named := case when p_branch is not null and p_branch <> 'both' and p_branch <> u.branch_slug
                  then array(select x.key from public.hub_units x where x.branch_slug = p_branch) else '{}' end;
  v_focus := case when cardinality(v_named) > 0 then v_named else v_keys end;
  v_rel := array(select t.parent_key from public.hub_topics t where t.key = any (p_topics) and t.parent_key is not null
                 union select t.key from public.hub_topics t where t.parent_key = any (p_topics));
  select coalesce(jsonb_agg(jsonb_build_object('id', z.id, 'key', z.key, 'title', z.live ->> ('title_' || v_lang), 'text', z.live ->> ('text_' || v_lang),
                                               'source', z.live ->> 'source', 'source_date', z.live ->> 'source_date', 'unit_keys', z.live -> 'unit_keys',
                                               'topic_keys', z.live -> 'topic_keys',
                                               'branch', (select x.branch_slug from public.hub_units x where x.key = (z.live -> 'unit_keys' ->> 0))) order by z.rank_unit, z.exact desc, z.related desc, z.sort, z.key), '[]'::jsonb)
    into v_cards from (
      select c.id, c.key, c.live, c.sort,
             case when c.unit_keys <@ v_focus and cardinality(c.unit_keys) > 0 then 0
                  when c.unit_keys && v_focus then 1
                  when cardinality(c.unit_keys) = 0 then 2
                  else 3 end as rank_unit,
             (select count(*) from unnest(c.topic_keys) k where k = any (p_topics)) as exact,
             (select count(*) from unnest(c.topic_keys) k where k = any (v_rel)) as related
        from (select k.id, k.key, k.live, k.sort, array(select jsonb_array_elements_text(k.live -> 'unit_keys')) as unit_keys,
                     array(select jsonb_array_elements_text(k.live -> 'topic_keys')) as topic_keys
                from (select x.id, x.key, x.sort, x.status,
                             case when x.id = any (coalesce(p_cards, '{}')) then false else x.is_test end as is_test,
                             case when x.id = any (coalesce(p_cards, '{}')) then internal.hub_card_snapshot(x) else x.live end as live
                        from public.hub_knowledge_cards x
                       where ((x.id = any (coalesce(p_cards, '{}')) and x.status <> 'archived') or (x.status = 'published' and x.live is not null)) and x.card_kind = 'fact') k
               where k.live is not null and not k.is_test
                 and ((k.live ->> 'expires_on') is null or (k.live ->> 'expires_on')::date >= v_today)) c
       where not (c.unit_keys && v_hidden)
         and (c.topic_keys && p_topics or c.topic_keys && v_rel)
         -- the café menu and ordering cards: on their own branch's numbers, or when the guest named that branch
         and (not (c.key = any (internal.hub_branch_only_cards())) or c.unit_keys && v_keys or c.unit_keys && v_named)
       order by rank_unit, exact desc, related desc, c.sort, c.key
       limit v_n) z;
  select coalesce(jsonb_agg(jsonb_build_object('key', z.key, 'q', z.live ->> ('q_' || v_lang), 'a', internal.hub_fill_fees(z.live ->> ('a_' || v_lang), v_lang))
                            order by z.mine desc, z.hits desc, z.sort, z.key), '[]'::jsonb)
    into v_faq from (
      select y.* from (
        select f.key, f.live, (f.live ->> 'sort')::int as sort,
               coalesce(t.unit_keys && v_focus, false) as mine,
               (select count(*) from unnest(coalesce(t.topic_keys, '{}')) k where k = any (p_topics)) * 2
               + (select count(*) from unnest(coalesce(t.topic_keys, '{}')) k where k = any (v_rel)) as hits
          from public.faq_items f left join public.hub_faq_topics t on t.faq_key = f.key
         where f.live is not null and not coalesce((f.live ->> 'hidden')::boolean, false) and not f.is_test) y
       where y.hits > 0
       order by y.mine desc, y.hits desc, y.sort, y.key
       limit v_n) z;
  return jsonb_build_object('unit', u.key, 'language', v_lang, 'branch', coalesce(p_branch, u.branch_slug), 'cards', v_cards, 'faq', v_faq);
end;
$$;

create or replace function internal.hub_learn_insert(p_kind text, p_scope text, p_who text, p_name text, p_user uuid, p jsonb, p_replaces text[], p_test boolean)
returns jsonb
language plpgsql security definer set search_path = '' as $$
declare
  v public.hub_knowledge_cards;
  v_check jsonb;
  v_today date := internal.riyadh_today();
  v_no smallint;
  v_old text;
  v_topics text[];
begin
  v_topics := array(select distinct x from jsonb_array_elements_text(coalesce(p -> 'topic_keys', '[]'::jsonb)) x
                     where exists (select 1 from public.hub_topics t where t.key = x and t.status = 'active' and not t.always_handoff));
  v.key := 'k-' || substr(replace(gen_random_uuid()::text, '-', ''), 1, 10);
  v.unit_keys := case when p_scope = 'both' then '{}'::text[]
                      else array(select u.key from public.hub_units u where u.kind = 'branch' and u.branch_slug = p_scope and not u.is_test) end;
  v.topic_keys := v_topics;
  v.title_ar := left(btrim(coalesce(p ->> 'title_ar', '')), 120);
  v.title_en := left(btrim(coalesce(p ->> 'title_en', '')), 120);
  v.text_ar := left(btrim(coalesce(p ->> 'text_ar', '')), 1200);
  v.text_en := left(btrim(coalesce(p ->> 'text_en', '')), 1200);
  v.card_kind := case when p ->> 'card_kind' = 'rule' and p_kind = 'teach' then 'rule' else 'fact' end;
  v.source := left((case when v.card_kind = 'rule' then 'قاعدة رد — ' when p_kind = 'teach' then 'تعليم واتساب — ' else 'رد الفريق — ' end) || coalesce(nullif(btrim(p_name), ''), 'الفريق') || ' — ' || internal.hub_date_ar(v_today), 300);
  v.source_date := v_today;
  -- H9 fix 1: a fact with a natural end that has not come yet (today up to 400 days); an end in the past is a standing answer
  v.expires_on := case when coalesce(p ->> 'expires_on', '') ~ '^20[0-9]{2}-[0-9]{2}-[0-9]{2}$' and (p ->> 'expires_on')::date between v_today and v_today + 400
                       then (p ->> 'expires_on')::date end;
  v.status := 'draft';
  v_check := internal.hub_card_check(v);
  if jsonb_array_length(v_check -> 'missing') > 0 then return jsonb_build_object('ok', false, 'reason', 'check', 'check', v_check); end if;
  v_old := internal.hub_learn_actor(p_user, case p_kind when 'teach' then 'تعليم واتساب — ' else 'رد الفريق — ' end || coalesce(nullif(btrim(p_name), ''), 'الفريق'));
  perform pg_advisory_xact_lock(hashtext('hub_learn_no'));
  v_no := coalesce((select max(k.learn_no) from public.hub_knowledge_cards k where k.learn_day = v_today), 0) + 1;
  insert into public.hub_knowledge_cards (card_kind, key, unit_keys, topic_keys, title_ar, title_en, text_ar, text_en, source, source_date, expires_on, verified_by, verified_at, status, sort,
                                          is_test, learn_kind, learn_scope, learn_who, learn_by_name, learn_day, learn_no, learn_short, learned_at, replaces_keys,
                                          published_at, published_by, first_published_at, created_by, updated_by)
  values (v.card_kind, v.key, v.unit_keys, v.topic_keys, v.title_ar, v.title_en, v.text_ar, v.text_en, v.source, v.source_date, v.expires_on, p_user, now(), 'draft',
          coalesce((select max(x.sort) + 1 from public.hub_knowledge_cards x), 0), coalesce(p_test, false), p_kind, p_scope, p_who, left(btrim(coalesce(p_name, '')), 80),
          v_today, v_no, nullif(left(btrim(coalesce(p ->> 'short_ar', '')), 80), ''), now(), coalesce(p_replaces, '{}'), now(), p_user, now(), p_user, p_user)
  returning * into v;
  update public.hub_knowledge_cards c set live = internal.hub_card_snapshot(c), status = 'published' where c.id = v.id returning * into v;
  if cardinality(coalesce(p_replaces, '{}')) > 0 then
    update public.hub_knowledge_cards c set status = 'archived', archived_at = now(), archived_by = p_user, updated_by = p_user
     where c.key = any (p_replaces) and c.status <> 'archived';
  end if;
  perform internal.hub_learn_actor_end(v_old);
  return jsonb_build_object('ok', true, 'id', v.id, 'key', v.key, 'n', v_no, 'day', v_today, 'wording', v.text_ar, 'expires_on', v.expires_on);
end;
$$;

create or replace function public.hub_teach_finish(p_job uuid, p jsonb) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare
  j public.hub_teach_jobs;
  m jsonb;
  t jsonb;
  v_cost numeric := 0;
  v_status text := case when p ->> 'status' in ('learned', 'ask', 'refused', 'failed', 'link', 'rule') then p ->> 'status' else 'failed' end;
  v_conflicts text[];
  v_r jsonb;
  v_old text;
  v_phone text;
  -- H9 fix 1: the teacher's own recent cards a follow-up replaces
  v_own text[] := '{}';
begin
  select * into j from public.hub_teach_jobs where id = p_job for update;
  if j.id is null then raise exception 'not_found' using errcode = '22023'; end if;
  if j.status <> 'running' then return jsonb_build_object('ok', false, 'reason', 'not_running'); end if;
  for m in select * from jsonb_array_elements(coalesce(p -> 'models', '[]'::jsonb)) loop
    if j.unit_id is not null and coalesce((m ->> 'input_tokens')::bigint, 0) + coalesce((m ->> 'output_tokens')::bigint, 0) > 0 then
      v_cost := v_cost + internal.hub_usage_add(j.unit_id, 'draft_card', 'staff', m ->> 'model', (m ->> 'input_tokens')::bigint, (m ->> 'output_tokens')::bigint, j.is_test);
    end if;
  end loop;
  v_phone := coalesce((select r.phone from public.hub_report_recipients r where 'recipient:' || r.id = j.who), (select s.phone from public.hub_staff_slots s where 'slot:' || s.id = j.who));
  t := internal.hub_teacher(v_phone);
  -- the teacher may still teach this scope (a slot changed since): checked again
  if v_status in ('learned', 'ask') and internal.hub_teach_verdict(t, j.scope) <> 'ok' then
    update public.hub_teach_jobs set status = 'refused', reason = 'not_allowed', cost_usd = cost_usd + v_cost, finished_at = now() where id = j.id;
    return jsonb_build_object('ok', true, 'line', 'not_allowed');
  end if;
  -- H9 fix 3 (Ahmed, 17 Nov 2026): a reply rule — the owner only; no contradiction question (a rule is not a fact)
  if v_status = 'rule' then
    if not coalesce((t ->> 'owner')::boolean, false) then
      update public.hub_teach_jobs set status = 'refused', reason = 'rule_owner', cost_usd = cost_usd + v_cost, finished_at = now() where id = j.id;
      return jsonb_build_object('ok', true, 'line', 'rule_owner');
    end if;
    v_r := internal.hub_learn_insert('teach', j.scope, j.who, t ->> 'name', nullif(t ->> 'owner_user', '')::uuid,
                                     coalesce(p -> 'card', '{}'::jsonb) || jsonb_build_object('card_kind', 'rule'),
                                     coalesce((select array_agg(k.key) from public.hub_knowledge_cards k where k.id = j.revises and k.status <> 'archived'), '{}'), j.is_test);
    if not coalesce((v_r ->> 'ok')::boolean, false) then
      update public.hub_teach_jobs set status = 'failed', reason = 'check', cost_usd = cost_usd + v_cost, finished_at = now() where id = j.id;
      return jsonb_build_object('ok', true, 'line', 'failed', 'check', v_r -> 'check');
    end if;
    update public.hub_teach_jobs set status = 'learned', card_id = (v_r ->> 'id')::uuid, cost_usd = cost_usd + v_cost, finished_at = now() where id = j.id;
    return jsonb_build_object('ok', true, 'line', case when nullif(btrim(coalesce(p ->> 'part', '')), '') is not null then 'rule_saved_part' else 'rule_saved' end,
      'vars', jsonb_build_object('wording', v_r ->> 'wording', 'n', v_r ->> 'n', 'branch', j.scope, 'part', left(btrim(coalesce(p ->> 'part', '')), 200)),
      'card_id', v_r ->> 'id', 'scope', j.scope, 'owner', true);
  end if;
  if v_status = 'ask' then
    v_conflicts := array(select distinct x from jsonb_array_elements_text(coalesce(p -> 'conflicts', '[]'::jsonb)) x
                          where exists (select 1 from public.hub_knowledge_cards k where k.key = x and k.status = 'published' and k.id is distinct from j.revises));
    if cardinality(v_conflicts) = 0 then v_status := 'learned'; end if;
    -- H9 fix 1: a contradiction only with the teacher's OWN card of the last 2 hours is a follow-up — the new card replaces
    -- it, never «أستبدل القديمة؟» (Ahmed sent the same teaching twice on 16 Nov 2026)
    if v_status = 'ask' and not exists (select 1 from public.hub_knowledge_cards k where k.key = any (v_conflicts)
                                         and not coalesce(k.learn_who = j.who and k.learn_kind = 'teach' and k.learned_at > now() - interval '2 hours', false)) then
      v_own := v_conflicts;
      v_status := 'learned';
    end if;
  end if;
  -- H9 fix 1: the teaching asks for a link the content does not hold — asked for, never invented; the next message completes it
  if v_status = 'link' then
    insert into public.hub_teach_followups (who, kind, card_id, body, scope, link_name, channel_id, is_test)
    values (j.who, 'link', j.revises, left(coalesce(j.body, (select m2.body from public.hub_staff_messages m2 where m2.id = j.staff_message_id), ''), 4000), j.scope,
            left(btrim(coalesce(p ->> 'name', '')), 40), j.channel_id, j.is_test)
    on conflict (who) do update set kind = 'link', card_id = excluded.card_id, body = excluded.body, scope = excluded.scope, link_name = excluded.link_name,
                                    channel_id = excluded.channel_id, is_test = excluded.is_test, created_at = now();
    update public.hub_teach_jobs set status = 'link', cost_usd = cost_usd + v_cost, finished_at = now() where id = j.id;
    return jsonb_build_object('ok', true, 'line', 'link_ask', 'vars', jsonb_build_object('name', left(btrim(coalesce(p ->> 'name', '')), 40)));
  end if;
  if v_status = 'ask' then
    -- a reception manager never replaces a card of both branches or of the other branch (Ahmed's)
    if not coalesce((t ->> 'owner')::boolean, false)
       and exists (select 1 from public.hub_knowledge_cards k where k.key = any (v_conflicts) and internal.hub_teach_verdict(t, internal.hub_card_scope(k)) <> 'ok') then
      update public.hub_teach_jobs set status = 'refused', reason = 'conflict_shared', cost_usd = cost_usd + v_cost, finished_at = now() where id = j.id;
      return jsonb_build_object('ok', true, 'line', 'conflict_shared',
        'vars', jsonb_build_object('old', (select k.text_ar from public.hub_knowledge_cards k where k.key = any (v_conflicts) order by k.sort limit 1)));
    end if;
    insert into public.hub_teach_pending (who, job_id, channel_id, scope, candidate, conflicts, is_test)
    values (j.who, j.id, j.channel_id, j.scope, coalesce(p -> 'card', '{}'::jsonb), v_conflicts, j.is_test)
    on conflict (who) do update set job_id = excluded.job_id, channel_id = excluded.channel_id, scope = excluded.scope, candidate = excluded.candidate,
                                    conflicts = excluded.conflicts, is_test = excluded.is_test, created_at = now();
    update public.hub_teach_jobs set status = 'asked', cost_usd = cost_usd + v_cost, finished_at = now() where id = j.id;
    return jsonb_build_object('ok', true, 'line', 'ask_replace',
      'vars', jsonb_build_object('wording', p #>> '{card,text_ar}', 'old', (select k.text_ar from public.hub_knowledge_cards k where k.key = any (v_conflicts) order by k.sort limit 1)));
  end if;
  if v_status = 'learned' then
    v_r := internal.hub_learn_insert('teach', j.scope, j.who, t ->> 'name', nullif(t ->> 'owner_user', '')::uuid, coalesce(p -> 'card', '{}'::jsonb),
                                     -- H9 fix 1: a follow-up or «عدّل» replaces the card it completes
                                     coalesce((select array_agg(k.key) from public.hub_knowledge_cards k where k.id = j.revises and k.status <> 'archived'), '{}') || v_own, j.is_test);
    if not coalesce((v_r ->> 'ok')::boolean, false) then
      update public.hub_teach_jobs set status = 'failed', reason = 'check', cost_usd = cost_usd + v_cost, finished_at = now() where id = j.id;
      return jsonb_build_object('ok', true, 'line', 'failed', 'check', v_r -> 'check');
    end if;
    update public.hub_teach_jobs set status = 'learned', card_id = (v_r ->> 'id')::uuid, cost_usd = cost_usd + v_cost, finished_at = now() where id = j.id;
    return jsonb_build_object('ok', true, 'line', case when j.revises is not null or cardinality(v_own) > 0 then 'revised' when j.scope = 'both' then 'saved_both' else 'saved' end,
      'vars', jsonb_build_object('wording', v_r ->> 'wording', 'n', v_r ->> 'n', 'branch', j.scope, 'expiry', v_r ->> 'expires_on'),
      'card_id', v_r ->> 'id', 'scope', j.scope, 'owner', coalesce((t ->> 'owner')::boolean, false));
  end if;
  update public.hub_teach_jobs set status = v_status, reason = case when p ->> 'reason' ~ '^[a-z_]{2,40}$' then p ->> 'reason' end, cost_usd = cost_usd + v_cost, finished_at = now()
   where id = j.id;
  return jsonb_build_object('ok', true, 'line', null);
end;
$$;

create or replace function public.hub_turn_queue(p_conversation uuid, p_message uuid) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare
  c public.hub_conversations;
  u public.hub_units;
  g public.guest_profiles;
  st jsonb;
  v_turn uuid;
  v_due timestamptz;
  v_kind text;
  -- at most 3 seconds (Ahmed, 15 Nov 2026 — the wait was the largest part of a reply's time)
  v_burst integer := least(greatest(internal.hub_setting_int('hub_burst_ms', 2000), 0), 3000);
  v_test_mode boolean;
  -- «وضع الاستعداد» (16 Nov 2026)
  v_wait integer;
  v_tap boolean;
  v_until timestamptz;
  v_woke boolean;
begin
  select * into c from public.hub_conversations where id = p_conversation for update;
  if c.id is null or c.state = 'closed' then return jsonb_build_object('queued', false, 'reason', 'closed'); end if;
  if not exists (select 1 from public.hub_messages m where m.id = p_message and m.conversation_id = c.id and m.direction = 'in' and m.author = 'guest') then
    return jsonb_build_object('queued', false, 'reason', 'not_guest');
  end if;
  select * into u from public.hub_units where id = c.unit_id;
  select * into g from public.guest_profiles where id = c.guest_profile_id;
  if g.hub_blocked_at is not null then return jsonb_build_object('queued', false, 'reason', 'blocked'); end if;
  st := internal.hub_assistant_state(u);
  if not (st ->> 'active')::boolean then
    perform internal.hub_to_team(c, case when st ->> 'reason' = 'unit_off' then 'assistant_off' else st ->> 'reason' end);
    return jsonb_build_object('queued', false, 'reason', st ->> 'reason');
  end if;
  v_test_mode := st ->> 'mode' = 'test';
  -- the try while the API credit is exhausted (at most every 30 minutes): reserved here
  if (st ->> 'credit_try')::boolean then
    update public.hub_alerts set payload = payload || jsonb_build_object('last_try_at', now()) where kind = 'api_credit' and acknowledged_at is null and not is_test;
  end if;
  if v_test_mode then
    -- a conversation that existed before «تجربة»: its run starts now
    if c.test_state is null then
      update public.hub_conversations set test_state = 'new' where id = c.id;
      c.test_state := 'new';
    end if;
    -- H6c: «بانتظار موظف» (a hand-off with no staff reply yet) is answered by the assistant in a test run as well
    v_kind := case when c.test_state = 'closed' then 'tag' else 'reply' end;
  else
    -- H6c: «بانتظار موظف» → the assistant keeps answering what it can; «مع موظف» → silent (tagging) until the branch's
    -- «عودة المساعد» minutes of staff silence, then the guest's message resumes it
    v_kind := case when c.state = 'human' and internal.hub_human_phase(c, u) is null then 'tag' else 'reply' end;
  end if;
  v_tap := exists (select 1 from public.hub_messages m where m.id = p_message and (m.kind in ('interactive', 'button_reply') or m.payload ? 'button_id'));
  v_woke := v_tap and exists (select 1 from public.hub_turns x where x.conversation_id = c.id and x.status = 'pending' and x.standby_until > now() and x.standby_outcome is null);
  -- a pending turn of this conversation takes the message (the burst; a wait of «وضع الاستعداد» takes every message until it
  -- ends — one reply to all of them); a tap on our own button ends the wait at once
  update public.hub_turns set inbound_message_ids = case when p_message = any (inbound_message_ids) then inbound_message_ids else inbound_message_ids || p_message end,
         due_at = case when v_tap and standby_until > now() and standby_outcome is null then least(due_at, now() + make_interval(secs => v_burst / 1000.0)) else due_at end,
         standby_until = case when v_tap and standby_until > now() and standby_outcome is null then now() else standby_until end
   where conversation_id = c.id and status = 'pending'
  returning id, due_at, standby_until into v_turn, v_due, v_until;
  if v_turn is not null then
    return jsonb_build_object('queued', true, 'joined', true, 'turn_id', v_turn, 'due_at', v_due, 'standby_until', case when v_until > now() then v_until end, 'woke', v_woke);
  end if;
  -- «وضع الاستعداد»: the minutes to wait for a staff reply first (NULL = none — today's burst)
  v_wait := internal.hub_standby_minutes(c.id, p_message, v_kind);
  insert into public.hub_turns (conversation_id, unit_id, inbound_message_ids, first_inbound_id, kind, due_at, is_test, standby_until, standby_reason)
  values (c.id, c.unit_id, array[p_message], p_message, v_kind,
          case when v_wait is not null then now() + make_interval(mins => v_wait) else now() + make_interval(secs => v_burst / 1000.0) end, c.is_test,
          case when v_wait is not null then now() + make_interval(mins => v_wait) end,
          -- H9 fix 3: why it waited or not (shown in «المحادثات» and «المحاكي»)
          internal.hub_standby_reason(c.id, p_message, v_kind))
  on conflict do nothing
  returning id, due_at into v_turn, v_due;
  if v_turn is null then
    select t.id, t.due_at into v_turn, v_due from public.hub_turns t where t.first_inbound_id = p_message;
    return jsonb_build_object('queued', false, 'reason', 'duplicate', 'turn_id', v_turn);
  end if;
  return jsonb_build_object('queued', true, 'turn_id', v_turn, 'due_at', v_due, 'kind', v_kind, 'standby_until', case when v_wait is not null then v_due end);
end;
$$;

create or replace function public.hub_thread(p_conversation uuid) returns jsonb
language plpgsql stable security definer set search_path = '' as $$
declare
  c public.hub_conversations;
  g public.guest_profiles;
  u public.hub_units;
  ch public.hub_channels;
  st jsonb;
begin
  select * into c from public.hub_conversations where id = p_conversation;
  if c.id is null or not internal.can_unit(c.unit_id, 'view') then raise exception 'not allowed' using errcode = '42501'; end if;
  select * into g from public.guest_profiles where id = c.guest_profile_id;
  select * into u from public.hub_units where id = c.unit_id;
  select * into ch from public.hub_channels where id = c.channel_id;
  st := internal.hub_assistant_state(u);
  return jsonb_build_object(
    'conversation', jsonb_build_object(
      'id', c.id, 'unit_id', u.id, 'unit_key', u.key, 'unit_kind', u.kind, 'branch', u.branch_slug,
      'unit_name', coalesce((select v.name_ar from public.dining_venues v where v.id = u.dining_venue_id), u.name_ar),
      'channel_kind', ch.kind, 'channel_address', ch.address, 'sending_enabled', ch.sending_enabled,
      'state', c.state, 'state_before_human', c.state_before_human, 'test_state', c.test_state, 'owner_kind', c.owner_kind, 'owner_staff_id', c.owner_staff_id,
      'owner_name', internal.staff_name(c.owner_staff_id), 'human_reason', c.human_reason, 'priority', c.priority,
      'language', coalesce(c.language, g.language), 'window_expires_at', c.window_expires_at, 'waiting_since', c.waiting_since,
      'last_guest_at', c.last_guest_at, 'last_staff_at', c.last_staff_at, 'tags', to_jsonb(c.tags), 'topics', to_jsonb(c.topics),
      'referral', c.referral, 'created_at', c.created_at, 'closed_at', c.closed_at, 'is_test', c.is_test,
      'can_edit', internal.can_unit(c.unit_id, 'edit'),
      'unit_mode', u.assistant_mode,
      'assistant', jsonb_build_object('active', (st ->> 'active')::boolean, 'mode', st ->> 'mode', 'reason', st ->> 'reason'),
      'can_release', internal.can_unit(c.unit_id, 'edit') and c.state = 'human' and (st ->> 'active')::boolean and st ->> 'mode' in ('shadow', 'licensed'),
      'can_pause', internal.can_unit(c.unit_id, 'edit') and u.assistant_mode <> 'off',
      -- «وضع الاستعداد»: the countdown «المساعد يرد بعد m:ss»
      'standby_until', internal.hub_standby_until(c.id),
      -- H9 fix 3: why the last turn waited or not («ينتظر رد الفريق» / «لم ينتظر: …»)
      'standby_last', internal.hub_standby_last(c.id),
      'templates_approved', (select coalesce(jsonb_agg(t.language order by t.language), '[]') from public.hub_templates t
                              where t.channel_id = c.channel_id and t.name = 'hub_reply_ready' and t.status = 'APPROVED')),
    'guest', jsonb_build_object(
      'id', g.id, 'name', g.name, 'wa_name', g.wa_profile_name, 'label', internal.hub_guest_label(g), 'phone', g.phone, 'language', g.language,
      'member', g.club_joined_at is not null, 'consent', g.consent, 'opted_out', g.wa_opt_out_at is not null, 'blocked', g.hub_blocked_at is not null,
      'marketing_hold', g.marketing_hold_at is not null, 'tags', to_jsonb(g.tags), 'notes', g.notes,
      'stays', (select count(*) from public.reservations r where r.profile_id = g.id and r.status = 'confirmed' and r.check_out <= (now() at time zone 'Asia/Riyadh')::date and not r.is_test),
      'last_stay', (select max(r.check_out) from public.reservations r where r.profile_id = g.id and r.status = 'confirmed' and r.check_out <= (now() at time zone 'Asia/Riyadh')::date and not r.is_test),
      'bookings', (select coalesce(jsonb_agg(jsonb_build_object('id', r.id, 'ref', r.ref, 'status', r.status, 'branch', r.branch, 'check_in', r.check_in, 'check_out', r.check_out)
                                             order by r.check_in desc), '[]')
                     from (select * from public.reservations r where r.profile_id = g.id and internal.can_branch(r.branch) order by r.check_in desc limit 10) r)),
    'messages', (select coalesce(jsonb_agg(jsonb_build_object(
                   'id', m.id, 'direction', m.direction, 'author', m.author, 'staff_id', m.staff_id, 'staff_name', internal.staff_name(m.staff_id),
                   'kind', m.kind, 'body', m.body, 'payload', m.payload, 'language', m.language, 'media_path', m.media_path, 'media_mime', m.media_mime,
                   -- H7: «تفريغ صوتي» and the image's category
                   'transcript', m.transcript, 'transcript_seconds', m.transcript_seconds, 'media_category', m.media_category, 'media_status', m.media_status,
                   'media_purged', m.media_purged_at is not null or m.media_pending_delete, 'status', m.status, 'error_code', m.error_code,
                   'sent_at', m.sent_at, 'purged', m.purged_at is not null, 'unanswered', exists (select 1 from public.hub_unanswered q where q.message_id = m.id),
                   'translation', m.translation_ar, 'approved_by_name', internal.staff_name(m.approved_by), 'approved_at', m.approved_at,
                   'edited_before_send', m.edited_before_send, 'turn_id', m.turn_id,
                   'sources', (select coalesce(jsonb_agg(jsonb_build_object('id', k.id, 'key', k.key, 'title', coalesce(k.live ->> 'title_ar', k.title_ar)) order by k.key), '[]')
                                 from public.hub_knowledge_cards k where k.id = any (m.source_card_ids)))
                   order by m.sent_at, m.created_at), '[]') from public.hub_messages m where m.conversation_id = c.id),
    'templates', (select coalesce(jsonb_agg(t order by t ->> 'at'), '[]') from (
                    select jsonb_build_object('source', 'booking', 'template', w.template, 'meta_template', w.meta_template, 'status', w.status, 'ref', w.ref,
                                              'branch', w.branch, 'language', w.language, 'at', w.created_at) t
                      from public.whatsapp_messages w join public.reservations r on r.id = w.reservation_id
                     where r.profile_id = g.id and internal.can_branch(r.branch) and w.status not in ('skipped')
                    union all
                    select jsonb_build_object('source', 'eyab', 'template', e.template, 'status', e.status, 'branch', e.branch, 'language', e.language, 'at', e.created_at)
                      from public.eyab_messages e where e.profile_id = g.id and e.status not in ('skipped') and internal.can_branch(e.branch)) s),
    'events', (select coalesce(jsonb_agg(jsonb_build_object('kind', e.kind, 'from', e.from_value, 'to', e.to_value, 'reason', e.reason, 'at', e.at,
                                                           'actor', internal.staff_name(e.actor_staff_id)) order by e.at, e.id), '[]')
                 from public.hub_conversation_events e where e.conversation_id = c.id),
    'episodes', (select coalesce(jsonb_agg(jsonb_build_object('id', x.id, 'unit_name', xu.name_ar, 'state', x.state, 'created_at', x.created_at, 'closed_at', x.closed_at)
                                           order by x.created_at desc), '[]')
                   from public.hub_conversations x join public.hub_units xu on xu.id = x.unit_id
                  where x.guest_profile_id = g.id and x.id <> c.id and internal.can_unit(x.unit_id, 'view')),
    'transfer_units', (select coalesce(jsonb_agg(jsonb_build_object('id', t.id, 'name', coalesce(v.name_ar, t.name_ar)) order by t.sort), '[]')
                         from public.hub_units t left join public.dining_venues v on v.id = t.dining_venue_id where t.status = 'active' and t.id <> u.id),
    'team', (select coalesce(jsonb_agg(jsonb_build_object('staff_id', s.user_id, 'full_name', s.full_name) order by s.full_name), '[]')
               from public.hub_unit_members m join public.staff s on s.user_id = m.staff_id
               join public.staff_permissions sp on sp.user_id = s.user_id and sp.section = 'inbox' and sp.level >= 'edit'
              where m.unit_id = u.id and s.active),
    'timers', internal.hub_timers());
end;
$$;

create or replace function public.hub_team_get() returns jsonb
language plpgsql stable security definer set search_path = '' as $$
declare
  v_edit boolean := internal.can('hub_team', 'edit');
  v_admin boolean := internal.is_system_admin();
begin
  if not internal.can('hub_team', 'view') then raise exception 'forbidden' using errcode = '42501'; end if;
  return jsonb_build_object(
    'now', now(), 'can_edit', v_edit, 'is_system_admin', v_admin,
    -- H9 fix 3: «أرقام التجربة» (the system admin only)
    'test_numbers', case when v_admin then (select coalesce(jsonb_agg(jsonb_build_object('id', n.id, 'phone', n.phone, 'label', n.label, 'created_at', n.created_at)
                                                                     order by n.created_at), '[]'::jsonb) from public.hub_test_numbers n) else '[]'::jsonb end,
    'branches', (select coalesce(jsonb_agg(jsonb_build_object(
        'slug', b.slug, 'name', b.name_ar, 'can_edit', v_edit and internal.can_branch(b.slug),
        'resume_minutes', t.resume_minutes, 'escalate_minutes', t.escalate_minutes,
        -- H9 fix 3: «الآن: ينتظر / لا ينتظر — السبب»
        'standby_now', public.hub_standby_now(b.slug), 'standby_on', t.standby_on, 'standby_minutes', t.standby_minutes,
        'channel', (select ch.sending_enabled from public.hub_channels ch where ch.id = internal.hub_branch_channel(b.slug)),
        'slots', (select coalesce(jsonb_agg(jsonb_build_object('id', s.id, 'position', s.position, 'name', s.name,
                    'phone', case when v_edit and internal.can_branch(b.slug) then s.phone else internal.hub_mask_phone(s.phone) end,
                    'role', s.role, 'days', to_jsonb(s.days), 'start_time', to_char(s.start_time, 'HH24:MI'), 'end_time', to_char(s.end_time, 'HH24:MI'),
                    'active', s.active, 'test_as_guest', s.test_as_guest, 'consent_at', s.consent_at,
                    'on_shift', s.active and internal.hub_slot_covers(s, now())) order by s.position), '[]'::jsonb)
                    from public.hub_staff_slots s where s.branch_slug = b.slug)
      ) order by b.sort, b.slug), '[]'::jsonb)
      from public.branches b join public.hub_team_branches t on t.branch_slug = b.slug where internal.can_branch(b.slug)),
    'report', jsonb_build_object(
      'send_time', (select to_char(c.send_time, 'HH24:MI') from public.hub_report_config c where c.id),
      'recipients', (select coalesce(jsonb_agg(jsonb_build_object('id', r.id, 'position', r.position, 'name', r.name,
                       'phone', case when v_admin then r.phone else internal.hub_mask_phone(r.phone) end, 'staff_user_id', r.staff_user_id,
                       'staff_name', internal.staff_name(r.staff_user_id), 'active', r.active, 'test_as_guest', r.test_as_guest, 'consent_at', r.consent_at,
                       'mine', r.staff_user_id = auth.uid()) order by r.position), '[]'::jsonb) from public.hub_report_recipients r),
      'email_recipients', (select count(*) from public.booking_notification_recipients r where r.scope = 'hub_summary' and r.active and r.filter_confirmed_at is not null),
      'last', (select jsonb_build_object('day', d.day, 'built_at', d.built_at) from public.hub_daily_reports d order by d.day desc limit 1),
      'staff_users', case when v_admin then (select coalesce(jsonb_agg(jsonb_build_object('id', s.user_id, 'name', s.full_name) order by s.full_name), '[]'::jsonb)
                                               from public.staff s where s.active) end));
end;
$$;

create or replace function public.hub_departures_overview() returns jsonb
language plpgsql stable security definer set search_path = '' as $$
declare v_today date := internal.riyadh_today();
begin
  if not internal.can('departures', 'view') then raise exception 'forbidden' using errcode = '42501'; end if;
  return jsonb_build_object('today', v_today, 'system_admin', internal.is_system_admin(), 'can_edit', internal.can('departures', 'edit'),
    'branches', (select coalesce(jsonb_agg(jsonb_build_object(
        'branch', f.branch_slug, 'check_on', f.check_on, 'review_on', f.review_on, 'remind_on', f.remind_on,
        'last_upload', (select jsonb_build_object('date', x.departure_date, 'at', x.created_at, 'kept', x.kept) from public.hub_departure_uploads x
                         where x.branch_slug = f.branch_slug and not x.is_test order by x.created_at desc limit 1),
        -- H9 fix 1: the list of TODAY (uploaded each morning by 07:00) and today's reminders
        'today_uploaded', exists (select 1 from public.hub_departure_uploads x where x.branch_slug = f.branch_slug and x.departure_date = v_today and not x.is_test),
        'tomorrow_uploaded', exists (select 1 from public.hub_departure_uploads x where x.branch_slug = f.branch_slug and x.departure_date = v_today + 1 and not x.is_test),
        'reminders', (select coalesce(jsonb_agg(jsonb_build_object('round', r.round, 'name', s.name, 'mode', r.mode, 'status', r.status, 'code', r.error_code, 'at', r.updated_at)
                                               order by r.created_at), '[]'::jsonb)
                        from public.hub_upload_reminders r left join public.hub_staff_slots s on s.id = r.slot_id
                       where r.branch_slug = f.branch_slug and r.day = v_today and not r.is_test),
        'today', (select jsonb_build_object('rows', count(*), 'sent', count(*) filter (where d.check_state in ('accepted', 'sent', 'delivered', 'read')),
                                            'leave', count(*) filter (where d.answer = 'leave'), 'extend', count(*) filter (where d.answer = 'extend'))
                    from public.hub_departures d where d.branch_slug = f.branch_slug and d.departure_date = v_today and not d.is_test))
        order by f.branch_slug), '[]'::jsonb)
      from public.hub_departure_config f where internal.can_branch(f.branch_slug)));
end;
$$;

create or replace function internal.hub_report_data(p_day date, p_to timestamptz default null) returns jsonb
language plpgsql stable security definer set search_path = '' as $$
declare
  v_from timestamptz := (p_day::timestamp at time zone 'Asia/Riyadh');
  v_to timestamptz := coalesce(p_to, ((p_day + 1)::timestamp at time zone 'Asia/Riyadh'));
  v_branches jsonb := '{}'::jsonb;
  b text;
  v jsonb;
begin
  foreach b in array array['airport-road', 'shafa-road'] loop
    with conv as (
           select distinct c.id from public.hub_conversations c join public.hub_units u on u.id = c.unit_id join public.hub_messages m on m.conversation_id = c.id
            where u.branch_slug = b and not c.is_test and m.direction = 'in' and m.author = 'guest' and m.sent_at >= v_from and m.sent_at < v_to),
         ho as (select h.* from public.hub_handoffs h where h.branch_slug = b and not h.is_test and h.created_at >= v_from and h.created_at < v_to),
         sends as (select s.* from public.hub_staff_sends s join ho on ho.id = s.handoff_id)
    select jsonb_build_object(
      'conversations', (select count(*) from conv),
      'handed', (select count(distinct ho.conversation_id) from ho),
      'assistant', (select count(*) from conv where not exists (select 1 from ho where ho.conversation_id = conv.id)
                       and exists (select 1 from public.hub_messages m where m.conversation_id = conv.id and m.author = 'assistant' and m.direction = 'out'
                                     and m.status in ('accepted', 'sent', 'delivered', 'read') and m.sent_at >= v_from and m.sent_at < v_to)),
      'reply_avg_min', (select round(avg(extract(epoch from (ho.first_reply_at - ho.created_at)) / 60.0))::integer from ho where ho.first_reply_at is not null),
      'replied', (select count(*) from ho where ho.first_reply_at is not null),
      'bookings', (select count(*) from public.reservations r where r.branch = b and r.booking_source = 'assistant_whatsapp' and not r.is_test
                     and r.created_at >= v_from and r.created_at < v_to),
      'reviews', (select count(*) from public.whatsapp_messages w where w.branch = b and w.template = 'stay_review' and not w.is_test
                    and w.status in ('accepted', 'sent', 'delivered', 'read') and w.created_at >= v_from and w.created_at < v_to)
                 -- H9: and the review requests of «قائمة المغادرين»
                 + (select count(*) from public.hub_departures d where d.branch_slug = b and not d.is_test
                      and d.review_state in ('accepted', 'sent', 'delivered', 'read') and d.review_at >= v_from and d.review_at < v_to),
      'unanswered', (select count(*) from public.hub_unanswered q join public.hub_units u on u.id = q.unit_id
                       where u.branch_slug = b and not q.is_test and q.created_at >= v_from and q.created_at < v_to),
      'model_failures', (select count(*) from public.hub_turns t join public.hub_units u on u.id = t.unit_id
                           where u.branch_slug = b and not t.is_test and t.status = 'failed' and t.created_at >= v_from and t.created_at < v_to),
      'send_failures', (select count(*) from public.hub_messages m join public.hub_conversations c on c.id = m.conversation_id join public.hub_units u on u.id = c.unit_id
                          where u.branch_slug = b and not c.is_test and m.direction = 'out' and m.status = 'failed' and m.created_at >= v_from and m.created_at < v_to)
                       + (select count(*) from sends where sends.status = 'failed'),
      -- H7: the voice notes and images that failed (never a cap: it has its own email)
      'voice_failures', (select count(*) from public.hub_messages m join public.hub_conversations c on c.id = m.conversation_id join public.hub_units u on u.id = c.unit_id
                           where u.branch_slug = b and not c.is_test and m.direction = 'in' and m.kind = 'audio'
                             and m.media_status in ('failed_download', 'failed_transcribe', 'empty', 'unknown_language') and m.created_at >= v_from and m.created_at < v_to),
      'image_failures', (select count(*) from public.hub_messages m join public.hub_conversations c on c.id = m.conversation_id join public.hub_units u on u.id = c.unit_id
                           where u.branch_slug = b and not c.is_test and m.direction = 'in' and m.kind = 'image'
                             and m.media_status in ('failed_download', 'failed_vision') and m.created_at >= v_from and m.created_at < v_to),
      -- 15 Nov 2026: the staff alerts of the branch's hand-offs refused or failed (never silent)
      'staff_refused', (select count(*) from sends where sends.status in ('failed', 'skipped') and coalesce(sends.error_code, '') <> 'qa'),
      'alerts_sent', (select count(*) from sends where sends.status in ('accepted', 'sent', 'delivered', 'read')),
      'alerts_delivered', (select count(*) from sends where sends.status in ('delivered', 'read')),
      'alerts_read', (select count(*) from sends where sends.status = 'read'),
      'escalated', (select count(*) from ho where ho.escalated_at is not null),
      'opened', (select count(*) from ho where ho.opened_at is not null),
      'opened_link', (select count(*) from ho where ho.opened_via = 'link'),
      'email_only', (select count(*) from ho where ho.status = 'email_only'),
      'reasons', (select coalesce(jsonb_object_agg(z.reason, z.n), '{}'::jsonb) from (select coalesce(ho.reason, 'handoff') as reason, count(*) as n from ho group by 1) z),
      -- H9 «الخروج أو التمديد»: the day's departures of the list — the checks sent, «خروج», «تمديد», no answer
      'dep_on', exists (select 1 from public.hub_departure_config f where f.branch_slug = b and (f.check_on or f.review_on))
                or exists (select 1 from public.hub_departures d where d.branch_slug = b and not d.is_test and d.departure_date = p_day),
      'dep_rows', (select count(*) from public.hub_departures d where d.branch_slug = b and not d.is_test and d.departure_date = p_day),
      'dep_sent', (select count(*) from public.hub_departures d where d.branch_slug = b and not d.is_test and d.departure_date = p_day
                     and d.check_state in ('accepted', 'sent', 'delivered', 'read')),
      'dep_leave', (select count(*) from public.hub_departures d where d.branch_slug = b and not d.is_test and d.departure_date = p_day and d.answer = 'leave'),
      'dep_extend', (select count(*) from public.hub_departures d where d.branch_slug = b and not d.is_test and d.departure_date = p_day and d.answer = 'extend'),
      'dep_none', (select count(*) from public.hub_departures d where d.branch_slug = b and not d.is_test and d.departure_date = p_day and d.answer is null
                     and d.check_state in ('accepted', 'sent', 'delivered', 'read')),
      'dep_dry', (select count(*) from public.hub_departures d where d.branch_slug = b and not d.is_test and d.departure_date = p_day and d.check_state = 'dry_run'),
      'dep_late', (select count(*) from public.hub_departures d where d.branch_slug = b and not d.is_test and d.departure_date = p_day
                     and d.check_state = 'skipped' and d.check_code in ('late', 'limit_late')),
      -- H9 fix 1: that day's morning list was not uploaded by 08:30 (a branch in use) — the 08:30 reminder's fault line
      'dep_missing', coalesce(p_to, now()) >= ((p_day)::timestamp + time '08:30') at time zone 'Asia/Riyadh'
                     and exists (select 1 from public.hub_departure_config f where f.branch_slug = b and f.remind_on)
                     and not exists (select 1 from public.hub_departure_uploads x where x.branch_slug = b and not x.is_test and x.departure_date = p_day
                                       and x.created_at < ((p_day)::timestamp + time '08:30') at time zone 'Asia/Riyadh')
    ) into v;
    v_branches := v_branches || jsonb_build_object(b, v);
  end loop;
  return jsonb_build_object('day', p_day, 'partial', p_to is not null, 'until', v_to, 'branches', v_branches,
    -- the daily and test reports refused or failed (they belong to no hand-off)
    'reports_refused', (select count(*) from public.hub_staff_sends s where s.kind in ('report', 'report_test') and s.status in ('failed', 'skipped')
                          and coalesce(s.error_code, '') <> 'qa' and not s.is_test and s.created_at >= v_from and s.created_at < v_to),
    -- H7b: the cards published from the dashboard (the learned ones are listed below)
    'cards', (select count(*) from public.hub_knowledge_cards k where not k.is_test and k.learn_kind is null and k.published_at >= v_from and k.published_at < v_to),
    -- H7b: the facts learned that day (teaching and staff replies), numbered for «امسح N» — still active; and what needs Ahmed's decision
    'learned', (select coalesce(jsonb_agg(jsonb_build_object('n', k.learn_no, 'short', coalesce(k.learn_short, k.title_ar), 'branch', k.learn_scope, 'kind', k.learn_kind,
                                                            'by', k.learn_by_name) order by k.learn_no), '[]'::jsonb)
                  from public.hub_knowledge_cards k where not k.is_test and k.learn_day = p_day and k.learn_no is not null and k.status <> 'archived' and k.learned_at <= v_to),
    'decisions', (select count(*) from public.hub_card_jobs j where not j.is_test and j.decision is not null and j.finished_at >= v_from and j.finished_at <= v_to),
    'budget_alerts', (select count(*) from public.hub_alerts a where a.kind in ('budget_pct', 'budget_cap', 'api_credit') and not a.is_test and a.created_at >= v_from and a.created_at < v_to),
    -- H9: the sends held back by the shared limit that day (kept and tried again — never dropped silently)
    'limit_deferred', (select count(*) from public.whatsapp_messages w where not w.is_test and w.deferred_at >= v_from and w.deferred_at < v_to)
                    + (select count(*) from public.eyab_messages e where not e.is_test and e.deferred_at >= v_from and e.deferred_at < v_to)
                    + (select count(*) from public.hub_departures d where not d.is_test and ((d.check_deferred_at >= v_from and d.check_deferred_at < v_to)
                                                                                         or (d.review_deferred_at >= v_from and d.review_deferred_at < v_to))),
    'built_at', now());
end;
$$;

create or replace function public.hub_staff_chat_begin(p jsonb) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare
  v_who jsonb := internal.hub_staff_lookup(p ->> 'phone');
  ch public.hub_channels;
  u public.hub_units;
  v_id uuid;
  v_branches text[];
  v_today jsonb;
  v_facts jsonb := '{}'::jsonb;
  b text;
  st jsonb;
begin
  if v_who is null then return jsonb_build_object('staff', false); end if;
  if (v_who ->> 'test_as_guest')::boolean then return jsonb_build_object('staff', false, 'test_as_guest', true); end if;
  select * into ch from public.hub_channels where address = p ->> 'channel' order by created_at limit 1;
  if ch.id is null then return jsonb_build_object('staff', true, 'ok', false, 'reason', 'no_channel'); end if;
  select * into u from public.hub_units where id = ch.unit_id;
  insert into public.hub_staff_messages (who_kind, who_id, channel_id, direction, body, provider_message_id, is_test, kind, audio_seconds)
  values (v_who ->> 'kind', (v_who ->> 'who_id')::uuid, ch.id, 'in', left(p ->> 'text', 4096), nullif(p ->> 'provider_id', ''), coalesce((p ->> 'is_test')::boolean, false),
          -- H9 fix 3: a voice note's transcript is the body
          case when p ->> 'kind' = 'audio' then 'audio' when p ->> 'kind' in ('interactive', 'button_reply') then 'button' else 'text' end,
          case when p ->> 'kind' = 'audio' and jsonb_typeof(p -> 'audio_seconds') = 'number' then least((p ->> 'audio_seconds')::numeric, 999999) end)
  on conflict (provider_message_id) do nothing
  returning id into v_id;
  if v_id is null then return jsonb_build_object('staff', true, 'ok', false, 'reason', 'duplicate'); end if;
  v_branches := case when jsonb_array_length(v_who -> 'branches') > 0 then array(select jsonb_array_elements_text(v_who -> 'branches')) else array['airport-road', 'shafa-road'] end;
  v_today := internal.hub_report_data((now() at time zone 'Asia/Riyadh')::date, now());
  foreach b in array v_branches loop
    v_facts := v_facts || jsonb_build_object(b, jsonb_build_object(
      'waiting_for_staff', (select count(*) from public.hub_conversations c join public.hub_units x on x.id = c.unit_id
                              where x.branch_slug = b and c.state = 'human' and c.owner_kind is null and not c.is_test),
      'with_staff', (select count(*) from public.hub_conversations c join public.hub_units x on x.id = c.unit_id
                       where x.branch_slug = b and c.state = 'human' and c.owner_kind in ('staff', 'phone') and not c.is_test),
      'on_shift_now', (select coalesce(jsonb_agg(s.name order by s.position), '[]'::jsonb) from public.hub_staff_slots s
                         where s.branch_slug = b and s.active and internal.hub_slot_covers(s, now())),
      'today', jsonb_build_object('conversations', v_today #> array['branches', b, 'conversations'], 'handed_to_team', v_today #> array['branches', b, 'handed'],
                                  'answered_by_us', v_today #> array['branches', b, 'assistant'], 'chat_bookings', v_today #> array['branches', b, 'bookings']),
      'links', (select coalesce(jsonb_agg('https://admin.armadaresidence.com/?hub_c=' || z.token), '[]'::jsonb)
                  from (select h.token from public.hub_handoffs h join public.hub_conversations c on c.id = h.conversation_id
                         where h.branch_slug = b and h.closed_at is null and c.state = 'human' and c.owner_kind is null and not h.is_test
                         order by h.created_at limit 3) z)));
  end loop;
  st := internal.hub_budget_state();
  return jsonb_build_object('staff', true, 'ok', true, 'message_id', v_id, 'kind', v_who ->> 'kind', 'name', split_part(btrim(v_who ->> 'name'), ' ', 1),
    'role', v_who ->> 'role', 'unit', jsonb_build_object('id', u.id, 'key', u.key, 'branch', u.branch_slug),
    'gate', internal.hub_engine_ready() and internal.hub_setting_bool('hub_assistant_on') and ch.sending_enabled
            and not coalesce((st ->> 'capped')::boolean, false) and not coalesce((st ->> 'unset')::boolean, false)
            and not coalesce((st ->> 'api_credit')::boolean, false),
    'facts', v_facts,
    'history', (select coalesce(jsonb_agg(jsonb_build_object('author', case when x.direction = 'in' then 'colleague' else 'us' end, 'body', x.body) order by x.created_at), '[]'::jsonb)
                  from (select m.* from public.hub_staff_messages m where m.who_id = (v_who ->> 'who_id')::uuid and m.id <> v_id and m.body is not null
                          and m.created_at > now() - interval '24 hours' order by m.created_at desc limit 10) x),
    'models', (select s.value from public.settings s where s.key = 'hub_models'),
    'prices', (select s.value from public.settings s where s.key = 'hub_model_prices'),
    'forbidden', to_jsonb(internal.hub_forbidden_terms()),
    'now', to_char(now() at time zone 'Asia/Riyadh', 'HH24:MI'));
end;
$$;


-- ───────────────────────────────────────────── 9. the test lab: the fix-3 conversations ─────────────────────────────────────────────
do $$
declare v_sort integer := coalesce((select max(sort) + 1 from public.hub_test_items), 0);
begin
  insert into public.hub_test_items (key, unit_key, language, messages, context, expect, note, tags, added_from, sort)
  select e ->> 'key', e ->> 'unit', e ->> 'language', e -> 'messages', coalesce(e -> 'context', '{}'::jsonb), e -> 'expect', e ->> 'note',
         array(select jsonb_array_elements_text(e -> 'tags')), 'seed', v_sort + (o - 1)::integer
    from jsonb_array_elements($fix3_bank$[{"key":"c143","unit":"airport-road","language":"ar","messages":["كم سعر الغرفة عندكم؟","يوم الخميس الجاي ليلة واحدة لشخصين بدون إفطار"],"expect":{"action":"conversation","steps":[{"outcome":["ask","answer"],"must_not_include":["يبدأ من","ابتداء","أقل سعر","ريال"]},{"outcome":["quote","ask"],"must_include":["الخميس","جمادى"],"must_not_include":["يبدأ من"]}]},"note":"a room price without dates → the dates and the guests asked, no price; then the dates → the room cards with the Hijri date","tags":["conversation","fix3","price"],"context":{}},{"key":"c144","unit":"shafa-road","language":"ar","messages":["بكم الغرفة المزدوجة؟","أبغى السعر بس بدون تواريخ"],"expect":{"action":"conversation","steps":[{"outcome":["ask","answer"],"must_not_include":["يبدأ من","ابتداء","ريال"]},{"outcome":"ask","must_include":["حسب تواريخ","armadaresidence.com"],"must_not_include":["يبدأ من","ريال"]}]},"note":"a type named without dates → the dates asked, no «يبدأ من»; a guest who insists without dates → the prices depend on the dates and the website link, no price","tags":["conversation","fix3","price"],"context":{}},{"key":"c145","unit":"airport-road","language":"en","messages":["How much is a room per night?","Next Thursday for 2 nights, 2 adults, no breakfast"],"expect":{"action":"conversation","steps":[{"outcome":["ask","answer"],"must_not_include":["starting at","from SAR","lowest"]},{"outcome":["quote","ask"],"must_not_include":["starting at","from SAR"]}]},"note":"English: a price question without dates → the dates and guests asked, never 'starting at'; then the dates → the cards","tags":["conversation","fix3","price"],"context":{}},{"key":"c146","unit":"airport-road","language":"ar","messages":["[voice] السلام عليكم. يا أخي معاكم سالم، أبي جناح غرفتين وصالة، إحنا أربعة أشخاص. أبيه يوم الخميس اللي جاي. كم تعطوني إياه؟","[voice] أقول لا تضحك علي، أنا أقول يوم الخميس اللي جاي، ليلة واحدة بدون إفطار","[tap:book:1]","سالم تجربة","[voice] لا عفواً، بيها يوم الخميس الجاي والخروج يوم الجمعة"],"expect":{"action":"conversation","steps":[{"outcome":["ask","answer"],"media":"transcribed","salaam":true,"must_not_include":["يبدأ من"]},{"outcome":["quote","ask"],"must_include":["نعتذر"],"must_not_include":["أيضًا","سيكمل معك"]},{"outcome":"ask"},{"outcome":"summary","must_include":["الخميس","ليلة واحدة","جمادى"]},{"outcome":["summary","quote"],"must_include":["الخميس","الجمعة","جمادى"],"must_not_include":["أيضًا"]}]},"note":"Ahmed's sequence of 17 Nov 2026 as a fictional conversation (voice notes): «الخميس اللي جاي» read by code, the annoyed correction handled with an apology and no hand-off, the name, a passed day «يوم 15» asked about (never the old summary), the voice correction → ONE summary for Thursday → Friday with the Hijri date","tags":["conversation","fix3","dates","correction"],"context":{}},{"key":"c147","unit":"airport-road","language":"ar","messages":["أبغى أحجز غرفة لشخصين من 10 ديسمبر إلى 12 ديسمبر بدون إفطار","[tap:book:1]","منى تجربة","لا، خليها من 11 ديسمبر إلى 13 ديسمبر"],"expect":{"action":"conversation","steps":[{"outcome":"quote"},{"outcome":"ask"},{"outcome":"summary","must_include":["10 ديسمبر","رجب"]},{"outcome":["summary","quote"],"must_include":["11 ديسمبر","13 ديسمبر"],"must_not_include":["10 ديسمبر"]}]},"note":"a correction typed after the summary: the dates patched at once and ONE new summary (never the old one again)","tags":["conversation","fix3","dates","correction"],"context":{}},{"key":"c148","unit":"shafa-road","language":"ar","messages":["أبغى أحجز غرفة لشخصين","قلت لك يوم الخميس الجاي ليلتين، ليش ما تفهم"],"expect":{"action":"conversation","steps":[{"outcome":"ask"},{"outcome":["ask","quote"],"must_include":["نعتذر"],"must_not_include":["أبلغنا الفريق","سيكمل معك"]}]},"note":"frustration during a booking: one short apology, the stay continues — never a complaint, never the team","tags":["conversation","fix3","frustration"],"context":{}},{"key":"c149","unit":"shafa-road","language":"ar","messages":["الغرفة وسخة والتكييف خربان من أمس"],"expect":{"action":"conversation","steps":[{"outcome":"handoff","priority":"high","must_include":["نأسف"]}]},"note":"a real complaint (cleanliness and maintenance) still goes to the team at once, high priority","tags":["conversation","fix3","complaint"],"context":{}},{"key":"c150","unit":"airport-road","language":"ar","messages":["أبغى أحجز من ٩ جمادى الآخرة ليلتين لشخص واحد"],"expect":{"action":"conversation","steps":[{"outcome":["ask","quote"],"must_not_include":["بالتقويم الميلادي","يبدأ من"]}]},"note":"a Hijri date is read by code (Umm al-Qura) — never «نتعامل بالميلادي»; the stay continues with both calendars","tags":["conversation","fix3","dates","hijri"],"context":{}},{"key":"c151","unit":"airport-road","language":"ar","messages":["أبي أحجز الويكند لشخصين","نعم"],"expect":{"action":"conversation","steps":[{"outcome":"ask","must_include":["هل تقصد","الخميس","السبت"]},{"outcome":["ask","quote"]}]},"note":"«الويكند» → Thursday to Saturday, confirmed with «نعم» / «تواريخ أخرى»; «نعم» continues the stay","tags":["conversation","fix3","dates"],"context":{}},{"key":"c152","unit":"shafa-road","language":"ar","messages":["نبي ٣ غرف لعائلة"],"expect":{"action":"conversation","steps":[{"outcome":"ask","must_not_include":["تحتاجون","لديكم","وصولكم","لكم","أسماءكم"]}]},"note":"a three-room family request: the details asked in the singular, only the numbers the guest gave (c115's guard flake)","tags":["conversation","fix3","group"],"context":{}}]$fix3_bank$::jsonb) with ordinality as x(e, o)
  on conflict (key) do nothing;
end $$;

